window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/matematica_2024.js"]=[{"title":"Converter antes de comparar as lentes","steps":["O limite visual é 100 × 10⁻³ = 0,1 mm.","Com a ocular, a hemácia mede 0,007 × 10 = 0,07 mm; a objetiva precisa ampliar pelo menos 0,1/0,07 ≈ 1,43 vez.","Entre as opções, 2 é o menor fator suficiente: lente I, A."],"alternatives":{"A":"A lente I produz 0,14 mm, acima do mínimo, com o menor aumento suficiente.","B":"A lente II permitiria visualizar, mas seu aumento é maior que o necessário.","C":"A lente III também permite visualizar, porém não tem a menor capacidade.","D":"A lente IV produz 0,077 mm, abaixo de 0,1 mm.","E":"A lente V produz 0,098 mm, ainda menor que o limite visual."},"takeaway":"Em problemas de mínimo, uma opção próxima do limite pode ser insuficiente: não arredonde antes da comparação.","key":"matematica:M118","area":"matematica","year":2024,"number":136,"answer":"A","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dígitos e letras têm conjuntos diferentes","steps":["Há cinco algarismos disponíveis: 1, 2, 5, 7 e 0. Para dois distintos e ordenados, são 5 × 4 escolhas.","As teclas 2, 5 e 7 contêm dez letras: ABC, JKL e PQRS. As três letras distintas e ordenadas dão 10 × 9 × 8.","Multiplique os blocos: 20 × 720 = 14 400 senhas, B."],"alternatives":{"A":"11 520 não corresponde ao produto das cinco/quatro escolhas de dígitos e dez/nove/oito de letras.","B":"14 400 respeita os caracteres disponíveis, a ordem dos blocos e a proibição de repetição.","C":"18 000 permite cinco escolhas também no segundo algarismo, repetindo-o indevidamente.","D":"312 000 usa as 26 letras do alfabeto, não somente as dez das teclas permitidas.","E":"390 000 combina letras de todo o alfabeto e repetição dos algarismos, ambas indevidas."},"takeaway":"Conte caracteres, não só teclas; duas letras diferentes podem estar na mesma tecla.","key":"matematica:M752","area":"matematica","year":2024,"number":138,"answer":"B","subject":"Probabilidade e Análise combinatória","topic":"Contagem e análise combinatória","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparar o conjunto de peças","steps":["Cada enfeite exige duas peças X e uma Y.","Na loja I, o custo é 2 × 3 + 1 = R$ 7; na II, é 2 × 2 + 4 = R$ 8.","A compra mais barata em uma única loja é na I, por R$ 7, alternativa A."],"alternatives":{"A":"Aplica as quantidades corretas e compara os custos totais das duas lojas.","B":"R$ 4 soma apenas uma peça de cada tipo na loja I.","C":"Na loja II, o conjunto custa R$ 8, não R$ 6.","D":"O componente isolado mais barato não basta para decidir o custo do conjunto.","E":"Embora X seja mais barato na II, a peça Y faz o custo total superar o da loja I."},"takeaway":"Monte a cesta exigida antes de comparar preços; o menor preço unitário pode não gerar o menor total.","key":"matematica:M810","area":"matematica","year":2024,"number":139,"answer":"A","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Trinta por cento a menos da quantidade de acertos","steps":["João acerta 0,75 × 200 = 150 questões e fica em muito bom, incluindo a fronteira de 75%.","Felipe acerta 70% de 150: 105 questões.","Sua taxa é 105/200 = 52,5%, conceito regular. A combinação é B, não uma diferença de 30 pontos percentuais."],"alternatives":{"A":"O conceito de João está certo, mas 52,5% é regular, não bom.","B":"A alternativa classifica corretamente 75% e 52,5% nas faixas dadas.","C":"Felipe não fica abaixo de 50%; ele acertou 105 das 200.","D":"João está exatamente em 75%, fronteira incluída em muito bom, não em bom.","E":"Os dois conceitos estão incompatíveis com as porcentagens calculadas."},"takeaway":"Distinga redução percentual relativa de subtração de pontos percentuais.","key":"matematica:M074","area":"matematica","year":2024,"number":140,"answer":"B","subject":"Aritmética e Matemática básica","topic":"Porcentagem e variações percentuais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Compor as duas dependências","steps":["No primeiro relacionamento, I de 1 a 3 produz II de 1,5 a 3,5.","No gráfico de III em função de II, há um mínimo em II = 3; o máximo do intervalo aparece numa extremidade.","III(1,5) = 2,5 e III(3,5) = 2. O máximo é 2,5, B."],"alternatives":{"A":"1,0 é o mínimo alcançado no ponto II = 3, não o máximo.","B":"2,5 é o valor no extremo II = 1,5, maior que o outro extremo permitido.","C":"3,0 pertence a outras entradas do gráfico, fora do trecho de II considerado para o máximo.","D":"3,5 é uma extremidade de II, não o máximo de III.","E":"4,0 ocorre em II = 0, que não é gerado por I entre 1 e 3."},"takeaway":"Na composição, encontre primeiro o intervalo intermediário; não aplique o intervalo original diretamente ao segundo gráfico.","key":"matematica:M339","area":"matematica","year":2024,"number":141,"answer":"B","subject":"Álgebra e Funções","topic":"Leitura e transformação de gráficos de funções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A primeira etapa já tem três figuras","steps":["Na etapa 1, são três figuras; em cada nova etapa, copia-se todo o conteúdo e acrescenta-se outra cópia.","A quantidade dobra, formando uma PG de primeiro termo 3 e razão 2.","Na etapa 20 ocorreram dezenove duplicações: 3 × 2¹⁹, alternativa A."],"alternatives":{"A":"3 × 2¹⁹ conta dezenove duplicações depois do primeiro conjunto de três.","B":"3 × 2²⁰ conta uma duplicação adicional à vigésima etapa.","C":"3 × 2²¹ conta duas duplicações a mais do que as realizadas.","D":"Subtrair uma unidade não corrige a contagem das etapas de duplicação.","E":"A expressão 3 × 2²⁰ − 3 corresponde a outra soma, não ao conteúdo após duplicações."},"takeaway":"No termo geral de uma PG, o expoente é n − 1 porque o primeiro termo já está presente.","key":"matematica:M324","area":"matematica","year":2024,"number":142,"answer":"A","subject":"Álgebra e Funções","topic":"Sequências, PA e PG","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Separar bilheteria e lucro das vendas","steps":["Previam-se 300 meias; com aumento de 50%, vendem-se 450 meias e 50 inteiras.","A bilheteria é 450 × 65 + 50 × 130 = R$ 35 750. Para cobrir R$ 34 350 e lucrar R$ 17 000, faltam R$ 15 600 de lucro com alimentos.","Pelo critério de margem de 60% das vendas adotado no item, as vendas precisam somar 15 600/0,60 = R$ 26 000, ou R$ 52 por pessoa: D."],"alternatives":{"A":"R$ 19,50 por pessoa não gera a parcela de lucro faltante.","B":"R$ 28,80 não fornece R$ 15 600 de lucro com 500 consumidores e margem de 60%.","C":"R$ 34 é apenas 17 000/500, ignorando custos e bilheteria.","D":"R$ 52 gera R$ 26 000 em vendas e R$ 15 600 na margem utilizada pelo item.","E":"R$ 68,70 é o custo de produção dividido pelo público, não o gasto requerido."},"takeaway":"Diferencie margem sobre vendas de acréscimo sobre custo: aqui o gabarito usa lucro como 60% da receita de alimentos.","key":"matematica:M228","area":"matematica","year":2024,"number":143,"answer":"D","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Girar um trapézio retângulo","steps":["O eixo coincide com o lado perpendicular às bases paralelas do trapézio.","Cada base gira formando um círculo; como ambas têm comprimentos positivos diferentes, surgem dois raios distintos.","O lado inclinado gera a superfície lateral de um tronco de cone, D."],"alternatives":{"A":"Um cone teria um dos raios nulo, o que não ocorre nesse trapézio.","B":"Um cilindro teria raios iguais, incompatíveis com as bases de tamanhos diferentes.","C":"Uma rotação contínua não gera as faces planas de uma pirâmide.","D":"Dois círculos de raios distintos ligados pela superfície gerada pelo lado inclinado formam um tronco de cone.","E":"O resultado tem bases circulares, não as bases poligonais de um tronco de pirâmide."},"takeaway":"Identifique as figuras geradas por cada segmento ao redor do eixo antes de nomear o sólido.","key":"matematica:M501","area":"matematica","year":2024,"number":144,"answer":"D","subject":"Geometria espacial","topic":"Visualização espacial, cortes e projeções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A redução de área é diferença de produtos","steps":["A área antiga é 110 × 75 = 8 250 m².","A nova área é 105 × 68 = 7 140 m².","A diferença é 8 250 − 7 140 = 1 110 m², D. Não basta multiplicar as reduções dos lados."],"alternatives":{"A":"24 corresponde à redução do perímetro, em metros, não à redução de área.","B":"35 resulta de 5 × 7, o produto das diferenças dos lados, que não é a diferença das áreas.","C":"555 é metade da diferença correta entre as áreas.","D":"1 110 m² é a subtração das áreas retangulares calculadas.","E":"1 145 não é a diferença entre 8 250 e 7 140 m²."},"takeaway":"Área usa duas dimensões multiplicadas; comparar retângulos exige comparar os produtos completos.","key":"matematica:M366","area":"matematica","year":2024,"number":145,"answer":"D","subject":"Geometria plana","topic":"Áreas e perímetros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Maximizar área com custos de telas diferentes","steps":["Usando todo o orçamento, 2 × 20L + 2 × 15C = 6 000, logo C = 200 − 4L/3.","A área é A(L) = 200L − 4L²/3, parábola côncava com máximo no vértice L = 75.","Então C = 100 e a área é 7 500 m². O maior lado mede 100 m, B, não 75 m."],"alternatives":{"A":"85 m não é o maior lado do par ótimo 75 m e 100 m.","B":"100 m é o maior lado da solução de área máxima e respeita o orçamento.","C":"175 m é possível em configurações mais estreitas, mas não na de área máxima.","D":"C = 200 forçaria L = 0 com o orçamento, não um galinheiro de área máxima.","E":"350 m excede até o limite de um lado C quando os demais comprimentos tendem a zero."},"takeaway":"Com custos distintos, área máxima não exige quadrado: a restrição relevante é o custo, não só o perímetro.","key":"matematica:M286","area":"matematica","year":2024,"number":146,"answer":"B","subject":"Álgebra e Funções","topic":"Função quadrática","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparar formas de escrever um racional","steps":["A posição II tem o número misto 4 1/2, igual a 4,5.","A posição IV tem 18/4 = 4,5 e V já exibe 4,5.","As posições iguais são II, IV e V, B. I é 4^(1/2) = 2; III é 10/45 e VI é 4/5, diferentes."],"alternatives":{"A":"I representa raiz quadrada de quatro, não o número misto quatro e meio.","B":"II, IV e V convertem-se todas em 4,5.","C":"III representa 10/45 = 2/9, diferente dos valores das outras duas posições.","D":"III e VI não equivalem a V: 2/9 e 0,8 são diferentes de 4,5.","E":"III, IV e VI contêm valores diferentes entre si."},"takeaway":"Diferencie número misto de expoente fracionário: a posição gráfica muda a operação.","key":"matematica:M171","area":"matematica","year":2024,"number":147,"answer":"B","subject":"Aritmética e Matemática básica","topic":"Operações, frações e sistemas de numeração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A assíntota identifica a temperatura ambiente","steps":["A curva se aproxima de 20 °C, de modo que a = 20.","No ponto t = 10, T = 60: 60 = 20 + 80b¹⁰, então b¹⁰ = 0,5.","Logo b = (0,5)^(1/10), alternativa C. O valor de b fica entre zero e um, compatível com resfriamento."],"alternatives":{"A":"log(0,5) é negativo e não é a base positiva da função exponencial apresentada.","B":"a = 100 não corresponde à assíntota e daria T(0) = 180.","C":"A raiz décima de 0,5 satisfaz o ponto de dez minutos e a tendência do gráfico.","D":"Dividir a raiz de quarenta por oitenta não equivale a extrair a raiz da razão 40/80.","E":"b = 40 produziria crescimento muito rápido, não a queda de temperatura."},"takeaway":"Leia a assíntota e um ponto conhecido; mantenha os parênteses ao isolar uma potência.","key":"matematica:M302","area":"matematica","year":2024,"number":148,"answer":"C","subject":"Álgebra e Funções","topic":"Funções exponenciais e logaritmos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A capacidade exige raiz cúbica","steps":["Com π = 3, o volume do cilindro é 3 × 3² × 15 = 405 cm³.","O cubo precisa de 80%: 0,8 × 405 = 324 cm³.","Sua aresta satisfaz a³ = 324 = 27 × 12, logo a = 3∛12 cm, E."],"alternatives":{"A":"Aresta 6 produz 216 cm³, abaixo dos 324 cm³ exigidos.","B":"Aresta 18 produz 5 832 cm³, muito acima da capacidade solicitada.","C":"6√6 não tem cubo igual a 324; foi usada uma raiz inadequada ao problema volumétrico.","D":"(6∛6)³ = 1 296, diferente do volume necessário.","E":"(3∛12)³ = 27 × 12 = 324, exatamente a capacidade pretendida."},"takeaway":"Volume de cubo exige raiz cúbica para obter aresta; uma redução de volume não é igual redução da aresta.","key":"matematica:M439","area":"matematica","year":2024,"number":149,"answer":"E","subject":"Geometria espacial","topic":"Volumes e capacidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Contar também os vãos junto às paredes","steps":["A divisória atravessa 3 m = 300 cm. Com n colunas de raio r, há n diâmetros e n + 1 vãos de no máximo 15 cm.","É necessário 2rn + 15(n + 1) ≥ 300, portanto n ≥ 285/(2r + 15), arredondando para cima.","Nas lojas I a V, são 12, 9, 8, 7 e 6 colunas, com custos de R$ 720, 630, 600, 630 e 720. O menor é III, C."],"alternatives":{"A":"I exige doze colunas de R$ 60, total R$ 720.","B":"II exige nove colunas de R$ 70, total R$ 630.","C":"III exige oito colunas de R$ 75, total R$ 600, o menor custo.","D":"IV exige sete colunas de R$ 90, total R$ 630.","E":"V exige seis colunas de R$ 120, total R$ 720."},"takeaway":"Em peças separadas por espaços, conte os vãos das extremidades e imponha um número inteiro de peças.","key":"matematica:M367","area":"matematica","year":2024,"number":150,"answer":"C","subject":"Geometria plana","topic":"Áreas e perímetros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparar saldos, não exportações isoladas","steps":["Saldo é exportação menos importação no mesmo mês.","Em janeiro de 2010, as importações superam as exportações, deixando S₂ negativo. Junho de 2010 tem S₃ = 17,1 − 14,8 = 2,3.","A diferença positiva em junho de 2009 é maior que 2,3. Logo S₁ > S₃ > S₂, alternativa A."],"alternatives":{"A":"A ordem corresponde à maior separação positiva, à menor positiva e ao saldo negativo.","B":"Coloca S₂ em primeiro, apesar de ser negativo.","C":"Também põe o saldo negativo acima dos dois positivos.","D":"Inverte S₁ e S₃, confundindo o nível de exportações com sua diferença para importações.","E":"Coloca S₂ acima de S₁ e ainda inverte a comparação dos saldos positivos."},"takeaway":"Em gráficos de duas curvas, o saldo é a diferença vertical, não a altura de uma curva sozinha.","key":"matematica:M553","area":"matematica","year":2024,"number":152,"answer":"A","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Média inclui todos os seis contratos","steps":["Some 36 + 17 + 27 + 13 + 13 + 13 = 119 minutos.","São seis serviços, inclusive os três que repetem o tempo 13.","A média é 119/6 ≈ 19,833; com uma casa decimal, 19,8 minutos, C."],"alternatives":{"A":"13,0 é a moda, o valor mais frequente, não a média.","B":"15,0 é a mediana dos seis tempos ordenados, não a média.","C":"19,8 é o arredondamento correto de 119/6 com uma casa decimal.","D":"20,0 seria o arredondamento para inteiro apresentado como decimal, não o solicitado.","E":"23,3 não resulta da divisão da soma 119 pelos seis contratos."},"takeaway":"Valores repetidos são observações diferentes: cada um deve entrar na soma e na contagem.","key":"matematica:M641","area":"matematica","year":2024,"number":154,"answer":"C","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Escolher a menor área que atende à exigência","steps":["A área do setor é α × πR²/360. Com π = 3, fica αR²/120.","Os sensores I a V cobrem 50, 121, 48, 128 e 75 m².","Entre os que cobrem pelo menos 70 m², V tem a menor área e, conforme o texto, o menor preço: E."],"alternatives":{"A":"I cobre 50 m², abaixo do mínimo de 70 m².","B":"II cobre 121 m², atende ao mínimo, mas custa mais que o V pela regra dada.","C":"III cobre apenas 48 m² e não atende à exigência.","D":"IV cobre 128 m², mais que o necessário e mais que o sensor V.","E":"V cobre 75 m², a menor cobertura entre as opções que atingem o mínimo."},"takeaway":"O menor preço pode corresponder ao menor valor viável, não ao menor valor absoluto das opções.","key":"matematica:M368","area":"matematica","year":2024,"number":155,"answer":"E","subject":"Geometria plana","topic":"Áreas e perímetros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Traduzir cada parcela da tarifa","steps":["O valor fixo entra uma única vez: R$ 2.","O tempo custa 0,26T e a distância custa 1,40D.","A soma é V = 2,00 + 0,26T + 1,40D, alternativa B."],"alternatives":{"A":"F já representa a tarifa fixa; multiplicá-la por 2,00 duplica o fator dado.","B":"Soma corretamente parcela fixa e cobranças proporcionais a tempo e distância.","C":"O coeficiente da distância não é um; deve ser 1,40.","D":"Omite os dois reais cobrados independentemente do percurso.","E":"Os coeficientes de tempo e distância não são ambos iguais a um."},"takeaway":"Conferir unidades ajuda: cada taxa precisa multiplicar a grandeza correspondente para produzir reais.","key":"matematica:M260","area":"matematica","year":2024,"number":156,"answer":"B","subject":"Álgebra e Funções","topic":"Função afim e modelos lineares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Preservar o total com nova taxa de entrega","steps":["O preço atual de cinco porções é 5 × 25 + 10 = R$ 135.","Na nova cobrança, 5x + 15 deve continuar igual a 135.","Logo 5x = 120 e x = R$ 24, alternativa C. A elevação de R$ 5 na entrega é dividida por cinco porções."],"alternatives":{"A":"R$ 12,50 reduziria o total muito além da compensação da entrega.","B":"R$ 20 desconta R$ 5 em cada porção, quando a diferença total é só R$ 5.","C":"R$ 24 reduz um real por porção e compensa os cinco reais adicionais da entrega.","D":"R$ 30 aumenta também o preço das porções, não conserva o total.","E":"R$ 37,50 não satisfaz a igualdade 5x + 15 = 135."},"takeaway":"Uma taxa fixa é paga por pedido, não por unidade: distribua sua variação pelo número de itens.","key":"matematica:M229","area":"matematica","year":2024,"number":157,"answer":"C","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparar a compra com e sem promoção","steps":["O tipo A custa R$ 4,20/L e exige 40 L, total R$ 168, com máscara grátis.","O tipo B exige 50 L: R$ 150 mais R$ 12,50 da máscara, total R$ 162,50.","A mistura mínima para ganhar a máscara usa 35 L de A e 6,25 L de B: R$ 165,75. O menor gasto é C."],"alternatives":{"A":"R$ 147 paga 35 L de A, que cobrem só 17,5 ha, menos que os vinte necessários.","B":"R$ 150 paga o defensivo B, mas omite a máscara obrigatória.","C":"R$ 162,50 cobre os vinte hectares com B e inclui a máscara.","D":"A combinação promocional custa R$ 165,75, superior à compra apenas de B com máscara.","E":"R$ 168 cobre a área com A e máscara gratuita, mas não é o mínimo."},"takeaway":"Brinde não garante economia: compare o custo completo da necessidade, inclusive compras mistas viáveis.","key":"matematica:M811","area":"matematica","year":2024,"number":158,"answer":"C","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dividir vazão pela área","steps":["Vazão tem unidade mL/s.","O fluxo é diretamente proporcional à vazão e inversamente proporcional à área em cm².","Dividir (mL/s) por cm² resulta em mL/(cm²·s), alternativa C."],"alternatives":{"A":"Multiplicar por tempo e área contraria a divisão indicada na definição.","B":"Colocar cm² no numerador torna o fluxo proporcional, não inverso, à área.","C":"Volume dividido por tempo e área fornece a unidade solicitada.","D":"cm²·s/mL é o inverso da unidade correta do fluxo.","E":"cm²/(mL·s) também inverte as posições de volume e área."},"takeaway":"Escreva a relação entre grandezas primeiro e só depois substitua cada uma por sua unidade.","key":"matematica:M120","area":"matematica","year":2024,"number":159,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Volume e tempo crescem em proporções diferentes","steps":["O volume da segunda piscina é 2,75/2,50 = 1,10 vez o primeiro.","O tempo deve ser 1,20 vez o primeiro.","Como vazão é volume/tempo, Q₂ = 6 000 × 1,10/1,20 = 5 500 L/min, D."],"alternatives":{"A":"8 250 não satisfaz a razão volume/tempo necessária ao aumento de vinte por cento no tempo.","B":"7 920 multiplica os aumentos, quando o tempo deve entrar no denominador.","C":"6 545 inverte a relação dos fatores de volume e tempo.","D":"5 500 fornece aumento de volume de dez por cento com aumento de tempo de vinte por cento.","E":"5 280 usa redução direta de vinte por cento em vez de dividir pelo fator 1,20."},"takeaway":"Uma grandeza no denominador varia inversamente: aumentar tempo não é aumentar vazão.","key":"matematica:M006","area":"matematica","year":2024,"number":160,"answer":"D","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A altura máxima pode ficar constante enquanto o volume sobe","steps":["A entrada fica no compartimento da direita, limitado pelo anteparo de altura H/2.","Ele atinge H/2 em 2 h: isso ocupa um sexto do volume total. Depois, a água transborda e preenche os outros compartimentos, mantendo o máximo em H/2 até 6 h.","De 6 a 12 h, toda a base participa da subida. O gráfico cresce, fica constante de 2 a 6 e volta a crescer mais lentamente: B."],"alternatives":{"A":"A indica um patamar terminando cedo demais, antes de os outros dois compartimentos atingirem H/2.","B":"B respeita os intervalos de enchimento e a redução da inclinação quando toda a base recebe água.","C":"C mantém o patamar até dez horas, incompatível com os volumes relativos.","D":"D apresenta degraus instantâneos de altura máxima que não correspondem ao enchimento com vazão constante.","E":"E inclui queda da maior altura, embora o máximo não diminua durante o enchimento."},"takeaway":"Altura máxima e volume acumulado são grandezas diferentes: transbordar pode aumentar volume sem mudar o máximo.","key":"matematica:M340","area":"matematica","year":2024,"number":161,"answer":"B","subject":"Álgebra e Funções","topic":"Leitura e transformação de gráficos de funções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As parcelas dispensadas devem ser as mais altas","steps":["Os valores crescem de uma parcela para a seguinte.","Em cem meses, certos meses de início permitem nove aniversários pagos pela imobiliária; outros, apenas oito.","Comprando em fevereiro, maio corresponde às parcelas 4, 16, ..., 100. São nove dispensas, mais tardias e maiores que as de abril ou maio: A."],"alternatives":{"A":"Fevereiro permite nove parcelas dispensadas, incluindo a centésima e maior.","B":"Abril gera dispensas 2, 14, ..., 98, menores que as de fevereiro.","C":"Maio gera 1, 13, ..., 97, também antecipando e reduzindo os valores dispensados.","D":"Junho gera maio nas posições 12 a 96, com apenas oito dispensas.","E":"Agosto gera maio nas posições 10 a 94, também apenas oito dispensas."},"takeaway":"Em parcelas crescentes, compare quantidade e posição dos descontos, não só a primeira oportunidade de recebê-los.","key":"matematica:M812","area":"matematica","year":2024,"number":162,"answer":"A","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Somar arcos e segmentos da correia","steps":["Os trechos retos medem 15 cm cada, totalizando 30 cm.","A polia menor, de raio 4 cm, tem contato em 150°: arco = (150/360) × 2 × 3 × 4 = 10 cm.","A maior, raio 8 cm, tem arco complementar de 210°: 28 cm. Total = 30 + 10 + 28 = 68 cm, D."],"alternatives":{"A":"54 cm não inclui corretamente os dois arcos de raios e ângulos diferentes.","B":"60 cm não é a soma dos trechos retos com os arcos calculados.","C":"66 cm não respeita simultaneamente os contatos de 150° e 210°.","D":"68 cm soma corretamente 30 cm retos, 10 cm no arco menor e 28 cm no maior.","E":"72 cm não corresponde aos comprimentos dos arcos com π aproximado por três."},"takeaway":"Correias sobre polias não percorrem necessariamente semicircunferências: use os ângulos efetivos de contato.","key":"matematica:M416","area":"matematica","year":2024,"number":163,"answer":"D","subject":"Geometria plana","topic":"Ângulos, circunferências e polígonos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O hospital é o centro do triângulo equilátero","steps":["Três postos a 10 km entre si formam um triângulo equilátero.","O ponto equidistante dos vértices é o circuncentro; no equilátero, coincide com o baricentro.","A altura é 5√3 e o raio circunscrito é dois terços dela: 10√3/3 ≈ 5,77 km, entre cinco e seis, C."],"alternatives":{"A":"Entre dois e três fica o raio inscrito, não a distância do centro aos vértices.","B":"A distância calculada 5,77 km não está entre quatro e cinco.","C":"O raio circunscrito fica aproximadamente em 5,77 km, dentro do intervalo.","D":"O intervalo de sete a oito não contém o resultado de 10√3/3.","E":"Entre oito e nove fica a altura do triângulo, não a distância pedida."},"takeaway":"No triângulo equilátero, o centro divide a altura em dois para um; identifique qual segmento é o raio.","key":"matematica:M396","area":"matematica","year":2024,"number":164,"answer":"C","subject":"Geometria plana","topic":"Semelhança, triângulos e teorema de Pitágoras","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Encontrar ambos vermelhos exige multiplicar","steps":["Se cada semáforo fica vermelho por t segundos, a chance individual é t/60.","Com independência, (t/60)² = 4/100, de modo que t/60 = 0,2 e t = 12 s.","A pergunta é a redução: 15 − 12 = 3 s, B, não o novo tempo vermelho."],"alternatives":{"A":"Reduzir 1,35 s não deixa a probabilidade conjunta igual a quatro por cento.","B":"A redução de três segundos deixa doze segundos vermelhos em cada ciclo.","C":"Reduzir nove segundos deixa apenas seis, levando a um por cento para ambos.","D":"Reduzir 12,60 s deixa 2,40 s e não satisfaz a probabilidade requerida.","E":"Reduzir 13,80 s deixa 1,20 s, também incompatível com a condição."},"takeaway":"Diferencie probabilidade individual, probabilidade conjunta e a variação de tempo pedida.","key":"matematica:M699","area":"matematica","year":2024,"number":165,"answer":"B","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A densidade é uma razão de razões","steps":["Escreva d(R) = P/A.","A região Q tem população P/2 e área 3A/4.","Então d(Q) = (P/2)/(3A/4) = (2/3)(P/A) = (2/3)d(R), E."],"alternatives":{"A":"O fator um quarto não resulta de dividir metade da população por três quartos da área.","B":"O fator metade considera só a mudança populacional e ignora a área.","C":"Três quartos descreve a proporção das áreas, não das densidades.","D":"Três meios é o inverso da razão correta de densidades.","E":"Dividir um meio por três quartos produz dois terços, como exige a definição."},"takeaway":"Quando numerador e denominador mudam, compare os fatores por divisão, não isoladamente.","key":"matematica:M397","area":"matematica","year":2024,"number":166,"answer":"E","subject":"Geometria plana","topic":"Semelhança, triângulos e teorema de Pitágoras","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Subtrair números mistos","steps":["As telas medem 3 + 1/2 = 7/2 e 4 + 5/6 = 29/6 polegadas.","A diferença positiva é 29/6 − 21/6 = 8/6 = 4/3.","Em decimal, 1,333... fica 1,3 com uma casa decimal: D."],"alternatives":{"A":"0,1 não corresponde à diferença entre 4,833... e 3,5.","B":"0,5 considera uma diferença parcial, não os dois números mistos completos.","C":"1,0 considera apenas a diferença entre as partes inteiras.","D":"1,3 é a representação aproximada de quatro terços com uma casa decimal.","E":"1,8 não resulta da subtração das partes inteiras e fracionárias completas."},"takeaway":"Converta números mistos em frações impróprias ou decimais antes de subtrair.","key":"matematica:M398","area":"matematica","year":2024,"number":167,"answer":"D","subject":"Geometria plana","topic":"Semelhança, triângulos e teorema de Pitágoras","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Amplitude não é frequência","steps":["Amplitude é a distância máxima à linha de equilíbrio, não a quantidade de oscilações.","Ela deve permanecer constante nos primeiros nove minutos e constante num valor maior nos onze restantes.","A apresenta exatamente os dois patamares de amplitude exigidos. Mudança de frequência, sozinha, não aprova o amortecedor."],"alternatives":{"A":"Mostra amplitude constante em cada trecho, com valor maior depois dos nove minutos.","B":"A amplitude no segundo trecho diminui ao longo do tempo, violando a constância.","C":"Não apresenta o aumento para um patamar maior e constante na estrada de chão.","D":"Mudar o número de oscilações sem aumentar a amplitude não cumpre o critério.","E":"A frequência muda, mas não produz a amplitude maior e constante exigida no segundo trecho."},"takeaway":"Marque a linha média e compare alturas dos picos; espaçamento entre picos mede período, não amplitude.","key":"matematica:M790","area":"matematica","year":2024,"number":168,"answer":"A","subject":"Trigonometria","topic":"Funções trigonométricas e fenômenos periódicos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dois erros e só depois o acerto","steps":["Adotando a convenção das alternativas, há 25 deslocamentos não triviais do alfabeto; a substituição identidade fica excluída.","Para acertar apenas na terceira, é preciso errar as duas primeiras: probabilidades 24/25 e 23/24, retirando tentativas falhas.","Na terceira restam 23 possibilidades e uma correta: (24/25) × (23/24) × (1/23), alternativa E."],"alternatives":{"A":"Somar probabilidades não representa a sequência de dois erros e um acerto.","B":"Embora use frações condicionais, a soma não modela a ocorrência conjunta das três etapas.","C":"Usa chances de acerto em todas as tentativas, não dois erros anteriores.","D":"Mantém denominadores iguais, contrariando a eliminação das tentativas frustradas.","E":"O produto respeita as duas falhas e a redução do conjunto de escolhas a cada etapa."},"takeaway":"Explicite a convenção de contagem: incluir o deslocamento zero daria outro universo, não o adotado pelas opções.","key":"matematica:M700","area":"matematica","year":2024,"number":169,"answer":"E","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma ordem de grandeza na energia","steps":["Como E₁ é um décimo de E₂, temos E₂/E₁ = 10.","Na expressão dada, M₂ − M₁ = (2/3)log₁₀(E₂/E₁) = 2/3.","Logo M₂ = 6,9 + 0,666... = 7,566..., aproximadamente 7,6: C."],"alternatives":{"A":"5,4 implicaria diminuir a magnitude apesar de a segunda energia ser maior.","B":"6,2 corresponde a aplicar a variação com sinal contrário.","C":"7,6 é o arredondamento de 6,9 + 2/3.","D":"8,2 não decorre do coeficiente dois terços aplicado ao logaritmo de dez.","E":"8,4 usa incremento de três meios, invertendo o coeficiente fornecido."},"takeaway":"Escalas logarítmicas comparam razões: dez vezes a energia não significa dez vezes a magnitude.","key":"matematica:M303","area":"matematica","year":2024,"number":170,"answer":"C","subject":"Álgebra e Funções","topic":"Funções exponenciais e logaritmos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mesmo perímetro, áreas diferentes","steps":["Com perímetro k, os lados são k/3, k/4 e k/6.","As áreas são k²√3/36, k²/16 e k²√3/24 para triângulo, quadrado e hexágono.","Os coeficientes são aproximadamente 0,0481, 0,0625 e 0,0722. O hexágono tem a maior área e sua fórmula está em A."],"alternatives":{"A":"Identifica corretamente a forma de maior área e substitui seu lado por k/6.","B":"Escolhe a forma correta, mas usa uma fórmula que toma k como lado, não perímetro.","C":"A área do quadrado está correta, mas é menor que a do hexágono com o mesmo perímetro.","D":"A área do triângulo está correta, mas é a menor das três.","E":"Além de escolher a forma menor, usa k como lado em vez de perímetro do triângulo."},"takeaway":"Em comparação com perímetro fixo, substitua o lado em função do perímetro antes de comparar áreas.","key":"matematica:M369","area":"matematica","year":2024,"number":171,"answer":"A","subject":"Geometria plana","topic":"Áreas e perímetros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O encontro depende da velocidade de aproximação","steps":["Os ônibus se aproximam à taxa de 250 + 150 = 400 m/min.","O encontro ocorre em 9 000/400 = 22,5 min, a 250 × 22,5 = 5 625 m do terminal 1.","Os limites das câmeras a partir desse terminal são 1 800, 4 500, 5 400, 6 300 e 9 000 m. O encontro fica na faixa IV, D."],"alternatives":{"A":"I cobre apenas os primeiros 1 800 m a partir do terminal 1.","B":"II vai de 1 800 a 4 500 m e termina antes do encontro.","C":"III vai de 4 500 a 5 400 m, ainda antes dos 5 625 m.","D":"IV cobre de 5 400 a 6 300 m e contém a posição calculada.","E":"V começa depois dos 6 300 m, além do ponto de encontro."},"takeaway":"Para móveis em sentidos opostos, some as velocidades; depois localize a posição no referencial escolhido.","key":"matematica:M230","area":"matematica","year":2024,"number":172,"answer":"D","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As porcentagens precisam do peso de cada setor","steps":["Há 80 funcionários no administrativo, 120 na logística e 200 na produção.","Até 25 anos: 16 + 30 + 80 = 126. Entre 25 e 45: 24 + 48 + 70 = 142. A partir de 45: 40 + 42 + 50 = 132.","A maior chance é da faixa entre 25 e 45 anos, com 142/400 = 35,5%: A."],"alternatives":{"A":"A faixa indicada é a que soma mais funcionários, critério correto para sorteio equiprovável.","B":"A faixa é correta, mas sua chance não decorre de superar mínimos percentuais em cada setor.","C":"Percentuais crescentes em setores não substituem a contagem global; essa faixa soma 126.","D":"Ter mais jovens na produção não faz sua soma total superar os 142 da faixa intermediária.","E":"Somar percentuais de grupos com tamanhos diferentes ignora os pesos dos setores."},"takeaway":"Converta percentuais em quantidades antes de combinar grupos de tamanhos distintos.","key":"matematica:M701","area":"matematica","year":2024,"number":173,"answer":"A","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Projetar elimina altura, não posição no piso","steps":["B e C estão no mesmo segmento vertical, portanto suas projeções coincidem.","A, D e E estão na outra parede; D e E têm posições diferentes sobre o piso, de modo que DE continua como um segmento.","Preservando as posições na malha, AB e CD chegam ao mesmo ponto do lado esquerdo, DE fica no lado direito e EF termina no piso. A figura é C."],"alternatives":{"A":"Transforma CD em trecho horizontal e não preserva corretamente a sequência projetada.","B":"Suprime o trecho entre as projeções de D e E, que não coincidem.","C":"Mantém a coincidência de B e C, a direção projetada de CD e o segmento DE antes de EF.","D":"Mantém um trecho indevido para BC, embora esse segmento vertical deva projetar-se num ponto.","E":"Mostra CD horizontal, contrariando o deslocamento de posição indicado na malha."},"takeaway":"Na projeção ortogonal no piso, descarte só a coordenada de altura; segmentos verticais colapsam num ponto.","key":"matematica:M502","area":"matematica","year":2024,"number":174,"answer":"C","subject":"Geometria espacial","topic":"Visualização espacial, cortes e projeções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A largura da folha vira circunferência","steps":["Na embalagem 1, h = 20 e 2πr = 10, logo r = 5/π e V₁ = 500/π.","Na embalagem 2, h = 10 e 2πr = 20, logo r = 10/π e V₂ = 1 000/π.","A maior capacidade é 1 000/π cm³, alternativa D; a área lateral é igual, mas os volumes são diferentes."],"alternatives":{"A":"4 000π usa a medida vinte como raio, não como comprimento da circunferência.","B":"2 000π também não converte a extensão da folha em circunferência.","C":"4 000/π é quatro vezes o volume maior e não usa r = 10/π.","D":"1 000/π é o volume da segunda embalagem, superior ao da primeira.","E":"500/π é o volume correto da embalagem 1, mas não é o maior."},"takeaway":"Ao enrolar um retângulo, uma dimensão vira altura e a outra vira comprimento de circunferência, não diâmetro.","key":"matematica:M440","area":"matematica","year":2024,"number":175,"answer":"D","subject":"Geometria espacial","topic":"Volumes e capacidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Extrapolar a reta, não os pontos isolados","steps":["Na reta de tendência, 2014 corresponde aproximadamente a 4 milhões e 2017 a 5 milhões.","O crescimento linear é de um milhão em três anos.","De 2014 a 2026 são doze anos, portanto o aumento é quatro milhões: previsão de 8 milhões, B."],"alternatives":{"A":"Sete milhões corresponde a uma projeção anterior, não aos doze anos após 2014.","B":"Oito milhões resulta da variação de quatro unidades sobre o valor inicial de quatro.","C":"Nove milhões superestima a continuação da taxa de um milhão a cada três anos.","D":"Dez milhões supõe inclinação superior à reta indicada.","E":"Onze milhões também não segue a inclinação observada da linha de tendência."},"takeaway":"Uma reta de tendência resume o comportamento: não ligue arbitrariamente os últimos pontos observados.","key":"matematica:M261","area":"matematica","year":2024,"number":176,"answer":"B","subject":"Álgebra e Funções","topic":"Função afim e modelos lineares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Custo fixo mais custo por mochila","steps":["Entre 30 e 50 mochilas, o custo aumenta R$ 600 para vinte unidades: R$ 30 por mochila.","Em trinta unidades, o variável é R$ 900; restam R$ 150 de custo fixo.","Para oitenta, C = 150 + 30 × 80 = R$ 2 550, alternativa C."],"alternatives":{"A":"R$ 2 400 considera só o custo variável e omite os R$ 150 fixos.","B":"R$ 2 520 usa proporcionalidade direta a partir de cem unidades, indevida com custo fixo.","C":"A função C(n) = 150 + 30n satisfaz os três valores e fornece R$ 2 550.","D":"R$ 2 700 não resulta da taxa de trinta reais e da parcela fixa de cento e cinquenta.","E":"R$ 2 800 também não satisfaz o modelo linear determinado pela tabela."},"takeaway":"Função afim não é necessariamente proporcionalidade direta: confira se existe uma parcela fixa.","key":"matematica:M262","area":"matematica","year":2024,"number":177,"answer":"C","subject":"Álgebra e Funções","topic":"Função afim e modelos lineares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ordenar antes de procurar o centro","steps":["Em ordem crescente, os valores são 46, 54, 60, 64, 64 e 66.","Há seis dados, então a mediana é a média do terceiro e do quarto.","(60 + 64)/2 = 62%, alternativa E; a ordem dos meses não substitui a ordenação numérica."],"alternatives":{"A":"56 é a média dos extremos 46 e 66, não dos dois valores centrais.","B":"58 não é a média dos valores centrais 60 e 64.","C":"59 é a média aritmética dos seis dados, não sua mediana.","D":"60 é apenas o menor dos dois valores centrais.","E":"62 é o ponto médio entre o terceiro e o quarto valores da lista ordenada."},"takeaway":"Para quantidade par de observações, a mediana pode ser um número que não aparece na lista.","key":"matematica:M642","area":"matematica","year":2024,"number":178,"answer":"E","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A divisão segue as horas totais","steps":["O pagamento conjunto é 40% de R$ 71 250 = R$ 28 500.","As horas são 4 × 5,5 = 22; 5 × 4 = 20; 6 × 2,5 = 15. Total: 57 horas, a R$ 500 cada.","Os pagamentos são R$ 11 000, R$ 10 000 e R$ 7 500. A maior diferença é R$ 3 500, C."],"alternatives":{"A":"R$ 1 000 é a diferença entre os dois primeiros pagamentos, não a maior.","B":"R$ 1 500 não é a diferença máxima entre os valores proporcionais calculados.","C":"R$ 3 500 corresponde à diferença entre 22 e 15 horas, a quinhentos reais por hora.","D":"R$ 3 800 não corresponde à taxa de quinhentos reais multiplicada pela diferença de sete horas.","E":"R$ 5 250 supera a diferença correta entre o maior e o menor pagamento."},"takeaway":"Converta dias e jornadas em horas totais; não distribua valores diretamente pelo número de dias.","key":"matematica:M007","area":"matematica","year":2024,"number":179,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pelo menos três exige três casos","steps":["Uma equipe de cinco pode ter três cardiologistas e dois neurologistas, quatro e um, ou cinco e zero.","Em cada caso, multiplique as combinações dos dois grupos: C(7,3)C(6,2), C(7,4)C(6,1) e C(7,5)C(6,0).","Some os casos disjuntos: 525 + 210 + 21 = 756 equipes. A expressão correspondente é E."],"alternatives":{"A":"Os fatores não corrigem todas as permutações da equipe e contam ordem indevidamente.","B":"Conta somente o caso de exatamente três cardiologistas e dois neurologistas.","C":"Soma escolhas isoladas sem formar corretamente equipes completas em cada caso.","D":"Troca a soma de casos por produtos de somas, incluindo combinações sem a composição exigida.","E":"Multiplica escolhas dentro de cada composição e soma as três composições permitidas."},"takeaway":"Use multiplicação para escolhas que ocorrem juntas e adição para casos alternativos, sem contar ordem numa equipe.","key":"matematica:M753","area":"matematica","year":2024,"number":180,"answer":"E","subject":"Probabilidade e Análise combinatória","topic":"Contagem e análise combinatória","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"matematica/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2024.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
